function readParams() {
  const num = (id, fallback, min, max, round) => {
    const el = document.getElementById(id);
    const raw = Number(el.value);
    let v = Number.isFinite(raw) ? raw : fallback;
    v = Math.min(max, Math.max(min, v));
    if (round) v = Math.round(v);
    if (raw !== v) el.value = String(v);
    return v;
  };
  return {
    speed: num('speed', 22, 3, 70),
    mass: num('mass', 1250, 200, 5000),
    length: num('carLength', 4.2, 2.4, 8),
    width: num('carWidth', 1.8, 1.2, 3.2),
    height: num('carHeight', 1.45, 0.9, 2.4),
    columns: num('columns', 12, 2, 18, true),
    rows: num('rows', 8, 2, 14, true),
    depth: num('depth', 2, 1, 3, true),
    brickMass: num('brickMass', 2.5, 0.3, 50),
    brickWidth: num('brickWidth', 0.5, 0.2, 1.2),
    brickHeight: num('brickHeight', 0.24, 0.08, 0.6),
    brickDepth: num('brickDepth', 0.2, 0.08, 0.6),
    gravity: num('gravity', 9.81, 0.5, 30),
    brickFriction: num('brickFriction', 0.72, 0.02, 1.6),
    brickRestitution: num('brickRestitution', 0.18, 0, 0.85),
    groundFriction: num('groundFriction', 0.85, 0.02, 1.6),
    trackLength: num('trackLength', 40, 18, 90)
  };
}

