function loop(now) {
  if (!lastNow) lastNow = now;
  let frameDt = (now - lastNow) / 1000;
  lastNow = now;
  if (frameDt > 0.05) frameDt = 0.05;
  if (!paused) {
    accumulator += frameDt * timeScale;
    const maxSteps = Math.ceil(4 * Math.max(1, timeScale));
    let steps = 0;
    while (accumulator >= DT && steps < maxSteps) {
      stepPhysics();
      accumulator -= DT;
      steps++;
    }
    const keep = DT * Math.max(1, timeScale);
    if (accumulator > keep) accumulator = keep;
  }
  syncGraphics();
  placeCamera(paused ? 0 : frameDt * timeScale, false);
  updateShadows();
  composer.render();
  requestAnimationFrame(loop);
}

