function syncTransport() {
  document.getElementById('pause').classList.toggle('active', paused);
  document.getElementById('play').classList.toggle('active', !paused);
  document.querySelectorAll('#speeds button').forEach((btn) => {
    btn.classList.toggle('active', Number(btn.dataset.speed) === timeScale);
  });
  document.querySelectorAll('#views button').forEach((btn) => {
    btn.classList.toggle('active', btn.dataset.view === viewMode);
  });
}
function setPaused(next) {
  paused = !!next;
  syncTransport();
}
function restart() {
  paused = false;
  syncTransport();
  lastNow = 0;
  buildSim(readParams());
}
